import datetime,hashlib,json,pathlib,re,subprocess,sys
import prepare as p
import fresh as f

def read(name):return json.loads((p.ROOT/name).read_text(encoding='utf-8'))
def timestamp(name):
    data=read(name)
    return data.get('finishedAt') or data.get('checkedAt') or data.get('verifiedAt') or 'See timestamped log'

def main():
    ci=read('ci-checks.json');checks=ci['response']['check_runs']
    assert len(checks)==6 and all(item['head_sha']==p.SHA and item['conclusion']=='success' for item in checks)
    for name in ('fresh-result.json','fresh-safety-result.json','fresh-persistence.json','t45b-result.json','staging-result.json','staging-network-readiness.json'):
        data=read(name);assert data['sha']==p.SHA and data['status']=='PASS',name
    for name in ('fresh-smoke.json','t45b-smoke.json','staging-smoke.json'):
        data=read(name);assert data['passed']==14 and data['failed']==data['skipped']==0,name
    for name in ('fresh-config-snapshot.json','t45b-config-snapshot.json','staging-config-snapshot.json'):assert not read(name)['reviewErrors'],name
    assert p.run(['git','status','--porcelain=v1','--untracked-files=all'],'final-source-clean')==''
    assert p.run(['git','rev-parse','HEAD'],'final-source-head')==p.SHA
    remote=p.run(['git','ls-remote','origin','refs/heads/release/pre-go-live'],'final-remote-head')
    assert remote.split()[0]==p.SHA
    listed={name:value for value,name in (line.split('  ',1) for line in (f.PACKAGE/'SHA256SUMS').read_text(encoding='utf-8').splitlines())}
    digests={name:f.digest(f.PACKAGE/name) for name in listed}
    assert digests==listed and all(digests[name]==value for name,value in f.M['files'].items())
    digests['SHA256SUMS']=f.digest(f.PACKAGE/'SHA256SUMS')
    stage=read('staging-environment.json')
    p.run([sys.executable,str(p.ROOT/'d3-package-gate.py'),'--expected-sha',p.SHA,'--expected-manifest-digest',digests[f.MANIFEST.name],'--expected-images-digest',digests[next(name for name in digests if name.endswith('images.tar'))]],'final-staging-identity-gate',timeout=150)
    lock={'sha':p.SHA,'version':f.M['version'],'recordedAt':p.now(),'digests':digests,'manifestDigest':digests[f.MANIFEST.name],'imageArchiveDigest':digests[next(name for name in digests if name.endswith('images.tar'))],'staging':{key:stage[key] for key in ('project','baseUrl','apiUrl','workers')},'preD3Status':'PASS_READY_FOR_USER_DIGEST_REVIEW','userApproval':{'status':'PENDING','approvedAt':None},'D3':'NOT_RUN'}
    p.save('candidate-lock.json',lock)
    rows=[('R1','Health, restart API và giữ dữ liệu'),('R2','Login/logout, phân quyền và hết hạn phiên'),('R3','VAHAN options, filter và preview'),('R4','Lịch sử, xóa và khôi phục'),('R5','Export all và export có lọc'),('R6','UI Health trên VAHAN thật'),('R7','Once/Monthly, từ chối Daily'),('R7b','Múi giờ Việt Nam/Ấn Độ'),('R8','VAHAN ≥100 case, ≥30 phút, ETA mỗi 60 giây'),('R9','Pause/resume, không mất hoặc chạy trùng case'),('R9b','Worker động và giới hạn theo runner thực tế'),('R10','Tắt lịch, dừng và xóa'),('R11','Retry, NO_DATA và dừng runner'),('R12','Mất/phục hồi mạng, kiểm mất/trùng case'),('R13','Maker Update bị từ chối'),('R14','CAPTCHA/OCR không lộ dữ liệu nhạy cảm trong log'),('R15','API đã gỡ bị từ chối'),('R17','Run History đúng quyền và kết quả'),('S3','Giới hạn đăng nhập'),('S5','Socket.IO origin'),('S6','Security headers'),('S7','API docs và SPA shell'),('S8','Runner identity theo scope đã duyệt'),('S10','Container hardening theo scope đã duyệt'),('O1','Health probe ngoài stack')]
    ledger=[]
    for item,description in rows:
        reason='D3 chưa bắt đầu; chờ người dùng review/chốt SHA và digest cuối. Không dùng CI, smoke, T45b hoặc navigation-only làm PASS D3.'
        if item in ('S8','S10'):reason='Deferred theo quyết định D-02 trong PLAN; không tự chuyển scope hoặc tính PASS.'
        ledger.append({'item':item,'description':description,'status':'NOT_RUN','sha':p.SHA,'manifestDigest':lock['manifestDigest'],'imageArchiveDigest':lock['imageArchiveDigest'],'recordedAt':p.now(),'startedAt':None,'finishedAt':None,'evidence':[],'reason':reason})
    p.save('D3-checklist.json',{'sha':p.SHA,'recordedAt':p.now(),'D3Started':False,'items':ledger,'etaCriteria':{'minimumCases':100,'minimumMinutes':30,'sampleIntervalSeconds':60,'medianAbsoluteRelativeError50to75PercentMax':0.25,'medianAbsoluteRelativeError75to100PercentMax':0.15,'networkOutages':'Ghi nhận mất mạng VAHAN và tính vào sai số theo quyết định trong ledger đã commit. Không pause/đổi worker/restart do người vận hành trong R8.'}})
    d3=['# Checklist D3 — chờ chốt digest','',f'- SHA: `{p.SHA}`.',f'- Staging: `{stage["baseUrl"]}`; project `{stage["project"]}`, {stage["workers"]} runner.',f'- Manifest SHA-256: `{lock["manifestDigest"]}`.',f'- Images TAR SHA-256: `{lock["imageArchiveDigest"]}`.','- Thời gian ở từng dòng hiện là thời điểm ghi nhận NOT_RUN; startedAt/finishedAt để null vì chưa chạy. Xem JSON để có SHA, digest và lý do riêng từng mục.','', '| Mục | Nội dung | Trạng thái | Lý do |','| --- | --- | --- | --- |']
    d3 += [f'| {row["item"]} | {row["description"]} | NOT_RUN | '+('Deferred theo D-02.' if row['item'] in ('S8','S10') else 'Chờ review/chốt gói và digest cuối.')+' |' for row in ledger]
    d3 += ['', '[Ledger có timestamp và danh tính gói ở từng dòng](D3-checklist.json).', '', 'R8 giữ ngưỡng đã duyệt: ≥100 case, ≥30 phút, mẫu mỗi 60 giây; trung vị |e| ≤25% ở 50–75%, ≤15% ở 75–100%. Ghi rõ downtime VAHAN và tính vào sai số; không chèn các fault injection R9–R12 vào lượt R8. Tất cả các case thu thập phải qua VAHAN thật.', '', 'Sau khi người dùng chốt gói, kiểm lại danh tính bằng lệnh dưới đây. Lệnh chỉ đọc và không chạy D3:', '', '```powershell', f'py -3 "{p.ROOT / "d3-package-gate.py"}" `',f'  --expected-sha {p.SHA} `',f'  --expected-manifest-digest {lock["manifestDigest"]} `',f'  --expected-images-digest {lock["imageArchiveDigest"]}','```','', 'Nếu gate không PASS, dừng trước D3. Khi D3 đã bắt đầu, không sửa source hoặc build lại artifact; lỗi cần đổi source/artifact phải dừng và báo người dùng.']
    (p.ROOT/'D3-checklist.md').write_text('\n'.join(d3)+'\n',encoding='utf-8')
    build=read('package-build.json');fresh=read('fresh-result.json');upgrade=read('t45b-result.json');staging=read('staging-result.json')
    run_url=checks[0]['html_url'].split('/job/')[0]
    lines=['# Release F cuối — kiểm chứng mới và staging trước D3','',f'- Candidate: `origin/release/pre-go-live`, SHA `{p.SHA}`; version/tag `{f.M["version"]}`.',f'- Local và remote khớp SHA; worktree build sạch `{p.TREE}`.',f'- Báo cáo UTC: `{p.now()}`.', '- Kết luận: **PASS phần chuẩn bị trước D3; sẵn sàng để người dùng review/chốt digest cuối. D3 vẫn NOT_RUN.**', '- Mọi PASS của candidate này được kiểm mới trên đúng source/artifact. Không mang kết quả PASS của candidate trước sang.', '', '| Mục trước D3 | Kết quả | Thời gian UTC | Evidence |','| --- | --- | --- | --- |',f'| CI đúng SHA | PASS — 6/6 | {ci["verifiedAt"]} | [GitHub run]({run_url}), [raw check-runs](ci-checks.json) |',f'| Build từ worktree sạch | PASS | {build["startedAt"]} → {build["finishedAt"]} | [build log](package-build.log), [worktree](worktree-clean.json), [HEAD](final-source-head.log), [remote](final-remote-head.log) |',f'| Manifest, revision/version, checksum | PASS | {timestamp("package-validation.json")} | [package validation](package-validation.json), [loaded images](fresh-loaded-images.json), [source integrity](fresh-extracted-source-integrity.json) |',f'| Cài offline trên daemon trống | PASS — đủ 4 image | {fresh["finishedAt"]} | [empty store](clean-engine.json), [load](fresh-docker-load.log), [runtime image IDs](fresh-installed-image-identity.json) |',f'| Smoke cài mới và DB role | PASS — 14/14, 0 fail/skip | {timestamp("fresh-smoke.json")} | [smoke](fresh-smoke.json), [migration](fresh-initial-migration.log), [schema](fresh-schema.log) |',f'| Migration cài mới lần hai | PASS | {timestamp("fresh-migration-rerun.json")} | [log](fresh-migration-rerun.log) |',f'| compose stop → launcher | PASS — script nguyên bản từ gói | {timestamp("fresh-restart.json")} | [restart](fresh-restart.log), [data/session persistence](fresh-persistence.json) |',f'| Guard sau khi mở lại DB | PASS — vẫn chặn lịch hoạt động | {timestamp("fresh-safety-result.json")} | [structured result](fresh-safety-result.json), [active-work rejection](fresh-active-work-guard.log), [read-only rejection](fresh-readonly-when-stopped.log) |',f'| Chromium sandbox/Tesseract | PASS | {timestamp("fresh-chromium-tesseract.json")} | [runtime](fresh-chromium-tesseract.log), [versions/dependencies](fresh-build-fingerprint.json) |',f'| T45b: bản cũ có dữ liệu → F cuối | PASS — 0012 → 0016 | {upgrade["finishedAt"]} | [result](t45b-result.json), [old API data](t45b-old-application-data.json), [migration](t45b-upgrade-migration.log) |','| T45b: backup và restore | PASS | Xem timestamp từng lệnh | [backup verification](t45b-backup-verification.json), [archive list](t45b-backup-list.log), [restored data](t45b-restored-data.log) |','| T45b: bảo toàn dữ liệu | PASS — 10 bảng khớp số dòng/nội dung | Xem timestamp từng lệnh | [before](t45b-data-before.log), [after](t45b-data-after.log), [after second migration](t45b-data-after-second-migration.log) |','| T45b: Once/Monthly, Daily và lịch sử | PASS — giữ Once/Monthly, xóa đúng 1 Daily có audit | Xem timestamp từng lệnh | [schedule before](t45b-schedules-before.log), [after](t45b-schedules-after.log), [audit](t45b-daily-removal-audit.log), [reports/history](t45b-reports-history-api.json) |','| T45b: idempotent và cấu hình | PASS | Xem timestamp từng lệnh | [rerun](t45b-migration-idempotent.log), [audit unchanged](t45b-audit-after-second-migration.log), [old keys preserved](t45b-config-preservation.json), [credential failure safety](t45b-negative-credential-safety.json) |',f'| Smoke sau nâng cấp | PASS — 14/14, 0 fail/skip | {timestamp("t45b-smoke.json")} | [smoke](t45b-smoke.json), [installed images](t45b-installed-image-identity.json) |',f'| Staging riêng từ chính gói cuối | PASS — 3 runner healthy | {staging["finishedAt"]} | [staging result](staging-result.json), [image identity](staging-image-identity.json), [clean data](staging-final-clean-data.log) |',f'| Smoke staging | PASS — 14/14, 0 fail/skip | {timestamp("staging-smoke.json")} | [smoke](staging-smoke.json) |',f'| Kết nối VAHAN thật trước D3 | PASS — 3/3 HTTPS navigation, TLS bật | {timestamp("staging-network-readiness.json")} | [navigation only](staging-network-readiness.json); không phải CAPTCHA/report/UI Health/D3 |','| Gate SHA/digest/stack | PASS với danh tính gói vừa tạo | Xem timestamp lệnh | [read-only gate](final-staging-identity-gate.log); chưa phải xác nhận digest của người dùng |','| D3 R1–R15/R17, S3/S5/S6/S7/S8/S10/O1 | NOT_RUN | Chưa có startedAt/finishedAt | [checklist](D3-checklist.md), [ledger từng mục](D3-checklist.json) |', '', '## Gói cuối để chốt','', '[Thư mục package](package/) — source ZIP, images TAR, manifest, SHA256SUMS. **Không sửa hoặc build lại gói sau các kiểm chứng này.**','', '| File | SHA-256 |','| --- | --- |']
    lines += [f'| [{name}](package/{name}) | `{value}` |' for name,value in digests.items()]
    lines += ['', '[Danh tính gói và trạng thái chờ duyệt](candidate-lock.json). Chưa có digest nào được tự coi là người dùng đã chốt.', '', '## Staging đã chuẩn bị','',f'- Web: [{stage["baseUrl"]}]({stage["baseUrl"]}); API: `{stage["apiUrl"]}`.',f'- Project: `{stage["project"]}`, 3 runner; chỉ stack này dành cho D3.',f'- Installed root: `{stage["root"]}`; cấu hình riêng được bảo vệ, không đính kèm credential.', '- Dữ liệu nghiệp vụ sạch: 0 báo cáo/job/session/queue/profile/file/lịch sau smoke và navigation; chỉ có bootstrap admin và tài khoản smoke đã vô hiệu hóa.', '- Snapshot cuối ghi đúng `runner.replicas = 3`: [staging config](staging-config-snapshot.json). [Fresh config](fresh-config-snapshot.json) và [T45b config](t45b-config-snapshot.json) được lưu riêng theo môi trường.', '- Các daemon thử cài mới/nâng cấp và service con đã dừng; volume và backup riêng được giữ để review. Staging tiếp tục chạy để chờ D3.', '', '## Phạm vi và các vấn đề đã xử lý','', '- Lỗi restart gốc đã sửa trong source và kiểm lại từ script **không chỉnh tay** giải nén từ gói cuối. Không dùng workaround mở PostgreSQL riêng trong ca stop → launcher đạt.', '- Lỗi mất reference PostgreSQL khi save/load trên store trống đã sửa. Gói cuối nạp được chính reference pin digest, không nhờ image có sẵn.', '- Hai test browser phụ thuộc thứ tự/timing đã sửa theo hợp đồng: Maker so sánh đúng bộ giá trị, thử hai thứ tự phản hồi; reader chỉ nhận body sau khi bắt đầu đọc. Không bỏ assertion về giá trị thiếu/thừa/trùng hoặc kết quả data/no-data.', '- Bản nền T45b là B `2bc878e…`, có dữ liệu kiểm thử lưu thật trong PostgreSQL từ trước khi build gói cuối: 3 report rows, job/session/queue, stored file, profile và Once/Monthly/Daily. **Nội dung synthetic, không phải kết quả VAHAN thật**; [asset provenance](baseline-resource-provenance.json). Tất cả phép kiểm nâng cấp cho gói cuối được chạy mới.', '- Cài sạch dùng daemon/store/container/volume ban đầu rỗng trên cùng Windows host, không phải VM/máy vật lý riêng. Đã kiểm đường offline độc lập với Docker store cũ và tạo staging riêng đúng lựa chọn của người dùng.', '- Mẫu RAM ngay sau Docker restart chưa đủ; staging chưa được tạo lúc đó. [Recheck](staging-host-headroom-recheck.json) xác nhận đủ headroom trước khi tạo 3 runner. Đây là chờ môi trường ổn định, không thay source/artifact.', '- Ca DB runtime password ngắn bị từ chối trên DB restore riêng; 10 bảng nghiệp vụ không đổi. Schema migration diễn ra trước bước kiểm credential; chi tiết được giữ trong [negative case](t45b-negative-credential-safety.json).', '- S8/S10 giữ Deferred theo D-02 trong scope release đã có; không tính PASS.', '', '## Điều kiện còn lại trước D3','', 'Người dùng review và chốt **SHA + digest gói cuối** ở trên, rồi ra lệnh bắt đầu D3 trên staging này. Trước khi bắt đầu, chạy lại identity gate với đúng các giá trị người dùng đã chốt. Nếu lệch, dừng; trong D3 không sửa source/build lại gói.', '', '## Lịch sử candidate bị loại','', '- `6a0d197…`: CI xanh nhưng fresh offline phát hiện mất reference PostgreSQL; không dùng gói đó. [Rejection](../release-F-6a0d1975d6e9-20261016T083407Z/REJECTED.md).', '- `5680ab5…`: CI bị chặn bởi test Maker phụ thuộc thứ tự; chưa build gói. [Rejection](../release-F-5680ab506697-20261016T084505Z/REJECTED.md).', '- `965a9ec…`: CI bị chặn bởi test streaming body phụ thuộc 300 ms; chưa build gói. [Rejection](../release-F-965a9eca42ef-20261016T085232Z/REJECTED.md).', '- Chỉ gói `0a67461…` trong thư mục này là candidate cuối được đề nghị review. D3 chưa chạy trên bất kỳ candidate nào trong lượt chuẩn bị này.', '', 'Evidence có SHA-256 riêng trong `evidence-SHA256SUMS`. Private dump/env và giá trị/hash credential không nằm trong evidence/package.']
    (p.ROOT/'REPORT.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
    credentials=[]
    for root in (pathlib.Path(read('fresh-environment.json')['root']),pathlib.Path(read('t45b-environment.json')['baselineRoot']),pathlib.Path(read('t45b-environment.json')['upgradedRoot']),pathlib.Path(stage['root'])):
        credentials.extend(value for key,value in f.values_at(root).items() if any(token in key for token in ('PASSWORD','TOKEN','SECRET','STATE_KEY')) and len(value)>=12)
    readable=[path for path in p.ROOT.rglob('*') if path.is_file() and 'package' not in path.relative_to(p.ROOT).parts and '__pycache__' not in path.parts and path.name!='evidence-SHA256SUMS']
    for path in readable:assert not any(secret in path.read_text(encoding='utf-8',errors='replace') for secret in credentials),'Known credential in review evidence: '+path.name
    p.save('evidence-secret-audit.json',{'sha':p.SHA,'checkedAt':p.now(),'status':'PASS','readableFilesScanned':len(readable),'knownCredentialOccurrences':0,'secretValuesAndCredentialHashesWithheld':True,'scope':'Exact-value scan of the credentials used in these installations, plus source archive forbidden-file checks. Not D3 CAPTCHA/OCR log-security verification.'})
    for name in ('REPORT.md','D3-checklist.md'):
        for target in re.findall(r'\]\(([^)]+)\)',(p.ROOT/name).read_text(encoding='utf-8')):
            assert target.startswith(('https://','http://')) or (p.ROOT/target).exists(),'Broken report link: '+target
    files=[path for path in p.ROOT.rglob('*') if path.is_file() and '__pycache__' not in path.parts and path.name!='evidence-SHA256SUMS']
    (p.ROOT/'evidence-SHA256SUMS').write_text(''.join(f'{f.digest(path)}  {path.relative_to(p.ROOT).as_posix()}\n' for path in sorted(files)),encoding='utf-8')
    print(json.dumps({'sha':p.SHA,'status':lock['preD3Status'],'manifestDigest':lock['manifestDigest'],'imageArchiveDigest':lock['imageArchiveDigest'],'report':str(p.ROOT/'REPORT.md'),'stagingUrl':stage['baseUrl'],'workers':stage['workers'],'evidenceFiles':len(files),'D3':'NOT_RUN'},indent=2))

if __name__=='__main__':main()
